        self.form.act_delete.enabled = self.dst1_adapter.as_ref().is_some_and(|adapter| adapter.state().get() == crawrad_binding::DatasetState::Browse && adapter.collection().cursor().is_some());
        self.form.act_cancel.enabled = self.dst1_adapter.as_ref().is_some_and(|adapter| adapter.state().get().can_modify());
        self.form.btn_insert.enabled = self.form.act_insert.enabled;
